instance TauCeti.SheafOfModules.isFiniteType_biprod : ∀ {C : Type u₁} [inst : CategoryTheory.Category.{v₁, u₁} C] {J : CategoryTheory.GrothendieckTopology C}
  {R : CategoryTheory.Sheaf J RingCat} [inst_1 : CategoryTheory.HasSheafify J AddCommGrpCat]
  [inst_2 : J.WEqualsLocallyBijective AddCommGrpCat]
  [inst_3 : ∀ (X : C), CategoryTheory.HasSheafify (J.over X) AddCommGrpCat]
  [inst_4 : ∀ (X : C), (J.over X).WEqualsLocallyBijective AddCommGrpCat] {M N : SheafOfModules R}
  [CategoryTheory.Limits.HasPullbacks C] [M.IsFiniteType] [N.IsFiniteType], (M ⊞ N).IsFiniteType

theorem TauCeti.cobaseChange_f : ∀ {C : Type u} [inst : CategoryTheory.Category.{v, u} C] [inst_1 : CategoryTheory.Preadditive C]
  (S : CategoryTheory.ShortComplex C) {X' Q : C} {u : S.X₁ ⟶ X'} {v : S.X₂ ⟶ Q} {w : X' ⟶ Q}
  (sq : CategoryTheory.IsPushout S.f u v w), (TauCeti.cobaseChange S sq).f ≍ w

theorem TauCeti.DenseGraphLimits.isIsoInvariant_homDensityParam : ∀ {Ω : Type u_1} [inst : MeasurableSpace Ω] {μ : MeasureTheory.Measure Ω}
  [inst_1 : MeasureTheory.IsProbabilityMeasure μ] (W : TauCeti.DenseGraphLimits.Graphon Ω μ),
  TauCeti.DenseGraphLimits.IsIsoInvariant (TauCeti.DenseGraphLimits.homDensityParam W)

theorem TauCeti.Hodge.HodgeStructureOn.dualTensorHom_mem_internalHom_piece : ∀ {W₁ : Type u} {W₂ : Type v} [inst : AddCommGroup W₁] [inst_1 : Module ℂ W₁] [inst_2 : AddCommGroup W₂]
  [inst_3 : Module ℂ W₂] {ω₁ : TauCeti.Hodge.Conjugation W₁} {ω₂ : TauCeti.Hodge.Conjugation W₂} {n₁ n₂ : ℤ}
  (hs₁ : TauCeti.Hodge.HodgeStructureOn W₁ ω₁ n₁) (hs₂ : TauCeti.Hodge.HodgeStructureOn W₂ ω₂ n₂) {p q : ℤ}
  {φ : Module.Dual ℂ W₁} {y : W₂},
  φ ∈ hs₁.dual.piece p → y ∈ hs₂.piece q → (dualTensorHom ℂ W₁ W₂) (φ ⊗ₜ[ℂ] y) ∈ (hs₁.internalHom hs₂).piece (p + q)

theorem TauCeti.Toric.Fan.faceAffineToricSchemeMap_comp_affineToricChartι_assoc : ∀ {N : Type u} {V : Type u_1} [inst : AddCommGroup N] [inst_1 : AddCommGroup V] [inst_2 : Module ℝ V] {i : N →+ V}
  {Φ : TauCeti.Toric.Fan i} (hΦ : Φ.IsRegular) {τ σ : ↑Φ.cones} (h : (↑τ).IsFaceOf ↑σ) {Z : AlgebraicGeometry.Scheme}
  (h_1 : Φ.algebraicRealization hΦ ⟶ Z),
  CategoryTheory.CategoryStruct.comp (TauCeti.Toric.faceAffineToricSchemeMap ⋯ h)
      (CategoryTheory.CategoryStruct.comp (Φ.affineToricChartι hΦ σ) h_1) =
    CategoryTheory.CategoryStruct.comp (Φ.affineToricChartι hΦ τ) h_1

theorem QuadraticMap.IsometryEquiv.spinGroupEquiv_apply : ∀ {R : Type u} [inst : CommRing R] {M₁ : Type v} [inst_1 : AddCommGroup M₁] [inst_2 : Module R M₁] {M₂ : Type w}
  [inst_3 : AddCommGroup M₂] [inst_4 : Module R M₂] {Q₁ : QuadraticForm R M₁} {Q₂ : QuadraticForm R M₂}
  (e : QuadraticMap.IsometryEquiv Q₁ Q₂) (x : ↥(spinGroup Q₁)), e.spinGroupEquiv x = e.toIsometry.spinGroupMap x

theorem Valuation.characteristicSubgroup_eq_comap_of_isEquiv : ∀ {A : Type u_1} [inst : Ring A] {Γ₀ : Type u_2} [inst_1 : LinearOrderedCommGroupWithZero Γ₀] {Γ₀' : Type u_3}
  [inst_2 : LinearOrderedCommGroupWithZero Γ₀'] {v : Valuation A Γ₀} {w : Valuation A Γ₀'} (h : v.IsEquiv w),
  v.characteristicSubgroup = TauCeti.ConvexSubgroup.comap h.valueGroupOrderIso w.characteristicSubgroup
